DO $$
DECLARE
  cur CURSOR FOR SELECT patient_id FROM appointments WHERE status = 'no_show' ORDER BY scheduled_at;
  rec RECORD;
  current_penalty INT;
BEGIN
  OPEN cur;
  LOOP
    FETCH cur INTO rec;
    EXIT WHEN NOT FOUND;
    SELECT penalty_points INTO current_penalty FROM patients WHERE patient_id = rec.patient_id;
    UPDATE patients SET penalty_points = penalty_points + current_penalty + 1 WHERE patient_id = rec.patient_id;
  END LOOP;
  CLOSE cur;
END $$;

SELECT * FROM patients ORDER BY patient_id;
